SELECT 'UAE' AS company, '2' AS hostingId, `ec_orders`.`id` AS ecOrderId, CONCAT('UAE','_','2','_',`ec_orders`.`id`) AS sysOrderId, `ec_orders`.`code` AS orderNo, DATE_FORMAT(`ec_orders`.`created_at`, '%m/%d/%Y %h:%i:%s %p') AS orderDate, DATE_FORMAT(CONVERT_TZ(`ec_orders`.`created_at`, 'SYSTEM', '-04:00'), '%m/%d/%Y %h:%i:%s %p') AS orderDate_GMT, 'ECommerce' AS slOrderType, '' AS whsCode, `ec_orders`.`status` AS ecOrderStatus, '' AS statusRemarks, `payments`.`payment_channel` AS payMethod, '0' AS postedToSAP, '' AS cardCode, `ec_customers`.`id` AS customerId FROM `ec_orders` LEFT JOIN `payments` ON `ec_orders`.`payment_id` = `payments`.`id` LEFT JOIN `ec_customers` ON `ec_customers`.`id` = `ec_orders`.`user_id`;